INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 62 anos, no 5º DPO de uma colectomia esquerda, apresenta-se com taquicardia (120 bpm), hipotensão (90/60 mmHg) e febre (38,6°C). O débito urinário caiu para 10 ml nas últimas 2 horas. Ao exame físico, o abdome está distendido e muito doloroso, com sinais de irritação peritoneal difusa. Qual o próximo passo imediato mais adequado para confirmar a suspeita de deiscência de anastomose com peritonite?", "options": {"a": "Observar por 24 horas e iniciar antibióticos.", "b": "Realizar tomografia computadorizada de abdome e pelve com contraste intravenoso.", "c": "Solicitar radiografia de tórax para ver pneumoperitônio.", "d": "Indicar laparotomia exploradora imediata sem necessidade de exames de imagem, dada a clínica de abdome agudo perfurativo.", "e": "Realizar paracentese diagnóstica à beira do leito."}, "answer": "d", "rationale": "Em um paciente com sinais claros de peritonite e instabilidade hemodinâmica no pós-operatório de cirurgia intestinal, a suspeita de deiscência de anastomose é altíssima. A exploração cirúrgica não deve ser retardada por exames de imagem se a clínica for soberana de abdome agudo infra-abdominal catastrófico.", "option_rationales": {"a": "Incorreta. A observação em vigência de peritonite e choque é fatal.", "b": "Incorreta. Em paciente estável, seria o melhor exame, mas na instabilidade com sinais óbvios de peritonite, o atraso pode ser fatal.", "c": "Incorreta. O pneumoperitônio é esperado após laparotomia recente, não sendo diagnóstico de nova perfuração no 5º DPO.", "d": "Correta. Conduta em abdome agudo cirúrgico instável.", "e": "Incorreta. Pouco útil no cenário de peritonite pós-op óbvia."}, "difficulty": "dificil", "tags": ["Cirurgia Geral", "Pós-operatório", "Deiscência", "Choque Séptico"]}', 46, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 3º DPO de uma cirurgia cardíaca complexa, o paciente evolui com oligúria severa. Os exames mostram Creatinina de 2,4 mg/dL (valor basal de 0,8 mg/dL) e potássio de 6,2 mEq/L. De acordo com os critérios KDIGO para Insuficiência Renal Aguda, este paciente encontra-se em qual estágio?", "options": {"a": "Estágio 1.", "b": "Estágio 2.", "c": "Estágio 3.", "d": "Estágio 4.", "e": "Fase de Reuperação."}, "answer": "c", "rationale": "O estágio 3 do KDIGO é definido por um aumento da creatinina plasmática ≥ 3 vezes o valor basal, ou creatinina ≥ 4,0 mg/dL com aumento agudo de pelo menos 0,5 mg/dL, ou início de terapia renal substitutiva. Aqui, 0,8 x 3 = 2,4 mg/dL. Além disso, a oligúria severa por mais de 12h também pontua para estágio 3.", "option_rationales": {"a": "Incorreta. Exige aumento de 1,5-1,9 vezes o basal.", "b": "Incorreta. Exige aumento de 2,0-2,9 vezes o basal.", "c": "Correta. O aumento foi exatamente de 3 vezes o basal (2,4 / 0,8 = 3).", "d": "Incorreta. Não existe estágio 4 no KDIGO agudo (vai até 3).", "e": "Incorreta. Paciente está em fase de agudização."}, "difficulty": "moderada", "tags": ["Terapia Intensiva", "Pós-operatório", "IRA", "KDIGO"]}', 47, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes obesos submetidos a cirurgias abdominais altas, qual o principal componente da estratégia ventilatória intraoperatória e pós-operatória precoce para prevenir atelectasias de absorção?", "options": {"a": "Uso de oxigênio a 100% (FiO2 1.0) constante.", "b": "Manutenção de PEEP (Pressão Positiva Expiratória Final) adequada e manobras de recrutamento alveolar.", "c": "Ventilação com baixos volumes correntes (4 ml/kg) e sem PEEP.", "d": "Extubação precoce com o paciente ainda profundamente sedado.", "e": "Uso de broncodilatadores sistematicamente."}, "answer": "b", "rationale": "O obeso fende à compressão pulmonar pelo abdome. A PEEP mantém os alvéolos abertos, evitando o colapso (atelectasia), que é a principal causa de shunt e hipoxemia no pós-op.", "option_rationales": {"a": "Incorreta. FiO2 muito alta favorece atelectasia de absorção (lavagem de nitrogênio).", "b": "Correta. Padrão de ventilação protetora no obeso.", "c": "Incorreta. Baixos volumes sem PEEP geram colapso alveolar progressivo.", "d": "Incorreta. A extubação deve ser com paciente desperto e com reflexos protegidos.", "e": "Incorreta. Não previnem atelectasia mecânica."}, "difficulty": "media", "tags": ["Anestesiologia", "Pós-operatório", "Atelectasia", "Obesidade"]}', 48, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Uma paciente de 28 anos, no 4º DPO de uma apendicectomia por apendicite supurada, apresenta febre de 38,2°C e descarga purulenta pela ferida operatória, restrita ao tecido subcutâneo. Não há sinais de comprometimento da aponeurose. De acordo com o CDC, esta infecção é classificada como:", "options": {"a": "Infecção de Sítio Cirúrgico Incisional Superficial.", "b": "Infecção de Sítio Cirúrgico Incisional Profunda.", "c": "Infecção de Sítio Cirúrgico de Órgão/Espaço.", "d": "Contaminação acidental da ferida.", "e": "Abscesso primário de parede."}, "answer": "a", "rationale": "A ISC superficial envolve apenas pele e tecido subcutâneo acima da aponeurose, ocorrendo geralmente nos primeiros 30 dias.", "option_rationales": {"a": "Correta. Classificação técnica do CDC.", "b": "Incorreta. Essa envolveria a fáscia e o músculo.", "c": "Incorreta. Essa envolveria a cavidade peritoneal (ex: abscesso intra-abdominal).", "d": "Incorreta. Contaminação é o momento da cirurgia, aqui já há infecção instalada.", "e": "Incorreta. O termo correto é ISC."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "ISC", "Infecção"]}', 49, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 55 anos, tabagista e etilista crônico, submetido a esofagectomia trans-hiatal. No 4º DPO, desenvolve confusão mental, tremores de extremidades e alucinações visuais (vê bichos na parede). O paciente está taquicárdico e hipertenso. Qual a síndrome neurológica pós-operatória mais provável e qual a medicação de suporte inicial necessária?", "options": {"a": "Demência de Alzheimer; rivastigmina.", "b": "Delirium Tremens; benzodiazepínicos e tiamina (Vit B1).", "c": "Encefalopatia hepática; lactulona.", "d": "Sindrome serotoninérgica; clorpromazina.", "e": "Acidente Vascular Cerebral; AAS."}, "answer": "b", "rationale": "O quadro de alucinações (zoopsias), tremores e instabilidade autonômica em um etilista após alguns dias de jejum/cirurgia é característico do Delirium Tremens. A tiamina é essencial para prevenir a Encefalopatia de Wernicke.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diagnóstico e conduta clássicos.", "c": "Incorreta. Não há sinais de insuficiência hepática aguda descritos.", "d": "Incorreta. Associada ao uso de antidepressivos/drogas serotoninérgicas.", "e": "Incorreta. Não explicaria o quadro psiquiátrico exuberante agudo sem déficit focal."}, "difficulty": "media", "tags": ["Clínica Médica", "Pós-operatório", "Etilismo", "Delirium Tremens"]}', 50, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório imediato de uma cirurgia abdominal longa, o paciente apresenta-se com choque. A monitorização mostra: Pressão Venosa Central (PVC) baixa, Débito Cardíaco (DC) baixo e Resistência Vascular Sistêmica (RVS) elevada. Qual o tipo de choque sugerido por este padrão hemodinâmico?", "options": {"a": "Choque Séptico.", "b": "Choque Hipovolêmico.", "c": "Choque Neurogênico.", "b": "Choque Anafilático.", "e": "Choque Cardiogênico."}, "answer": "b", "rationale": "PVC baixa indica baixo volume intravascular (baixa pré-carga). RVS elevada é a resposta compensatória (vasoconstrição) para tentar manter a pressão.", "option_rationales": {"a": "Incorreta. Séptico costuma ter RVS baixa (vasodilatação).", "b": "Correta. Padrão clássico de hipovolemia por perda sanguínea ou desidratação.", "c": "Incorreta. Neurogênico tem PVC baixa mas RVS também baixa (perda de tônus simpático).", "d": "Incorreta. Anafilático tem RVS muito baixa.", "e": "Incorreta. Cardiogênico tem PVC alta (congestão) e DC baixo."}, "difficulty": "media", "tags": ["Terapia Intensiva", "Pós-operatório", "Choque", "Hemodinâmica"]}', 51, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 70 anos, com DPOC, é submetido a uma cirurgia de correção de hérnia incisiva gigante com uso de tela. No 2º DPO, ele apresenta dificuldade respiratória progressiva e acidose respiratória no exame de gasometria (pH 7.28, pCO2 58 mmHg). Ao exame físico, o abdome está muito tenso e a pressão inspiratória no ventilador está alta. A medição da PIA é de 22 mmHg. Além do suporte ventilatório, qual a medida clínica inicial para tentar reduzir a pressão intra-abdominal antes da reoperação?", "options": {"a": "Aumentar a infusão de cristaloides.", "b": "Posicionamento em decúbito ventral (prona).", "c": "Sonda gástrica e retal para descompressão, redução da sedação se possível e otimização da analgesia para reduzir prensa abdominal.", "d": "Administrar bicarbonato de sódio EV.", "e": "Realizar paracentese de alívio mesmo em abdome sem ascite."}, "answer": "c", "rationale": "O manejo conservador da Hipertensão Intra-abdominal (HIA) inclui a evacuação do conteúdo luminal (SNG, enemas), a melhora da complacência da parede abdominal (analgesia, sedação) e o balanço hídrico negativo/neutro.", "option_rationales": {"a": "Incorreta. Piora a HIA por edema de alças.", "b": "Incorreta. Prona é difícil no pós-op abdominal e pode aumentar a pia se não bem feita.", "c": "Correta. Medidas clínicas iniciais eficazes.", "d": "Incorreta. Trata o pH, mas não a causa mecânica.", "e": "Incorreta. Paracentese só funciona se houver líquido (ascite)."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "HIA", "Manejo Clínico"]}', 52, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual o principal distúrbio ácido-básico esperado em um paciente com fístula pancreática ou biliar de alto débito (ex: 1 litro/dia), considerando a composição das secreções?", "options": {"a": "Acidose metabólica hiperclorêmica (com anion gap normal).", "b": "Alcalose metabólica hipoclorêmica.", "c": "Acidose metabólica com anion gap elevado.", "d": "Alcalose respiratória compensada.", "e": "Acidose lática."}, "answer": "a", "rationale": "A secreção pancreática e biliar é rica em bicarbonato. A perda direta de bicarbonato leva a uma acidose metabólica, onde o organismo retém cloro para manter a eletroneutralidade, resultando em hipercloremia e anion gap normal.", "option_rationales": {"a": "Correta. Fisiopatologia da perda de fluidos alcalinos.", "b": "Incorreta. Isso ocorreria em vômitos gástricos (perda de H+ e Cl-).", "c": "Incorreta. O anion gap elevado sugere produção de ácidos orgânicos (lactato, cetoácidos).", "d": "Incorreta. A causa é metabólica primária.", "e": "Incorreta. Ocorre em choque/hipoperfusão."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Equilíbrio Ácido-Básico", "Fístula"]}', 53, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em uma paciente submetida a tireoidectomia total, a ocorrência de rouquidão e soprosidade na voz com engasgos frequentes para líquidos levanta a suspeita de lesão de qual nervo?", "options": {"a": "Nervo Laríngeo Superior bialteral.", "b": "Nervo Laríngeo Recorrente unilateral.", "c": "Nervo Frênico.", "d": "Nervo Espinal Acessório.", "e": "Nervo Ansa Cervical."}, "answer": "b", "rationale": "O nervo laríngeo recorrente inerva quase todos os músculos intrínsecos da laringe. Sua lesão unilateral causa paralisia da prega vocal em posição paramediana, levando a escape de ar (soprosidade) e risco de aspiração.", "option_rationales": {"a": "Incorreta. Causaria perda de tons agudos e alteração da sensibilidade, mas a rouquidão franca é do recorrente.", "b": "Correta. Lesão nervosa mais comum e temida na tireoidectomia.", "c": "Incorreta. Inerva o diafragma.", "d": "Incorreta. Inerva o trapézio.", "e": "Incorreta. Inerva músculos infra-hióideos."}, "difficulty": "facil", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Nervo Recorrente", "Complicações"]}', 54, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a herniorrafia inguinal pela técnica de Lichtenstein (com tela) apresenta, no 30º DPO, dor crônica tipo queimação e pontadas na região da virilha que irradia para a base do pênis e face interna da coxa. A dor piora ao caminhar. Qual o diagnóstico e o nervo provavelmente envolvido?", "options": {"a": "Orquite; nervo pudendo.", "b": "Inguinalghia crônica; nervo íleo-inguinal ou genitofemoral.", "c": "Recidiva da hérnia; nervo femoral.", "d": "Hérnia de disco lombar; nervo ciático.", "e": "Abscesso de tela; nervo obturador."}, "answer": "b", "rationale": "A dor crônica pós-herniorrafia (ingunodinia) é frequentemente causada pela compressão ou aprisionamento de nervos sensoriais (íleo-inguinal, íleo-hipogástrico ou genitofemoral) pela tela ou pela fibrose cicatricial.", "option_rationales": {"a": "Incorreta. Orquite causaria edema testicular agudo.", "b": "Correta. Complicação crônica comum após Lichtenstein.", "c": "Incorreta. Recidiva causaria abaulamento palpável.", "d": "Incorreta. Irradiaria para o território posterior da perna.", "e": "Incorreta. Causaria febre e sinais inflamatórios locais."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Herniorrafia", "Dor Crônica"]}', 55, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A profilaxia para tromboembolismo venoso (TEV) é obrigatória em pacientes submetidos a grandes cirurgias. Em um paciente submetido a cirurgia oncológica pélvica, qual a duração recomendada da profilaxia farmacológica com Heparina de Baixo Peso Molecular (HBPM) no pós-operatório, de acordo com as principais diretrizes (ACCP/SBACV)?", "options": {"a": "Apenas durante a internação hospitalar.", "b": "Até 7 dias após a cirurgia.", "c": "Atendimento estendido por 28 a 35 dias após a cirurgia.", "d": "Apenas se o paciente tiver TVP prévia.", "e": "Por 3 meses ininterruptos."}, "answer": "c", "rationale": "Pacientes submetidos a grandes cirurgias oncológicas abdominais ou pélvicas possuem alto risco mantido de TEV após a alta. A profilaxia estendida (cerca de 4 semanas) reduz significativamente a incidência de eventos tromboembólicos.", "option_rationales": {"a": "Incorreta. Insuficiente para o risco oncológico residual.", "b": "Incorreta. Tempo muito curto.", "c": "Correta. Recomendação atual das sociedades de cirurgia e hematologia.", "d": "Incorreta. Todos os pacientes de alto risco cirúrgico devem receber.", "e": "Incorreta. 3 meses é tempo de tratamento de TVP instalada, não de profilaxia de rotina."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Profilaxia TEV", "Oncologia"]}', 56, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 48 anos, em 1º DPO de uma gastrectomia, apresenta drenagem de 1.200 ml de secreção serossanguinolenta pelo dreno abdominal nas últimas 8 horas. O paciente está pálido, taquicárdico (FC 125 bpm) e com PA de 90/55 mmHg. Qual a estimativa de perda sanguínea baseada na classificação de choque do ATLS?", "options": {"a": "Classe I (< 15%).", "b": "Classe II (15-30%).", "c": "Classe III (30-40%).", "d": "Classe IV (> 40%).", "e": "Paciente está estável."}, "answer": "c", "rationale": "A presença de hipotensão arterial associada a taquicardia importante e palidez em um adulto indica perda volêmica volumosa, caracterizando choque Classe III (perda de 1.500 a 2.000 ml em um paciente de 70 kg, ou queda da PA).", "option_rationales": {"a": "Incorreta. Classe I mantém sinais vitais normais.", "b": "Incorreta. Classe II tem taquicardia mas mantém a pressão arterial sistólica normal.", "c": "Correta. Hipotensão é o marcador diferencial entre Classe II e III.", "d": "Incorreta. Classe IV tem sinais de choque franco impossível de manter sem transfusão maciça e letargia extrema.", "e": "Incorreta. Claramente instável hemodinamicamente."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Choque", "ATLS"]}', 57, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 6º DPO de uma revascularização do miocárdio, o paciente apresenta febre, dor retroesternal, drenagem purulenta pela ferida operatória e instabilidade esternal à palpação (crepitação do esterno). Qual a complicação infecciosa e a conduta imediata?", "options": {"a": "Mediastinite aguda; desbridamento cirúrgico e antibioticoterapia venosa.", "b": "Pneumonia hospitalar; apenas antibiótico.", "c": "Seroma de externo; punção local.", "d": "Endocardite bacteriana; ecocardiograma.", "e": "Empiema pleural; drenagem de tórax."}, "answer": "a", "rationale": "A mediastinite é uma complicação gravíssima após esternotomia, caracterizada por dor profunda e instabilidade óssea. O tratamento exige abertura, limpeza e antibióticos de amplo espectro.", "option_rationales": {"a": "Correta. Diagnóstico e conduta resolutiva.", "b": "Incorreta. Não explicaria a instabilidade esternal.", "c": "Incorreta. Seroma não causa pus ou instabilidade óssea.", "d": "Incorreta. Pode ocorrer, mas o quadro local é de ferida operatória.", "e": "Incorreta. Diferencial importante, mas a instabilidade óssea aponta para mediastinite."}, "difficulty": "moderada", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Mediastinite", "Infecção"]}', 58, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual o principal eletrólito cuja deficiência (hipo) está associada a arritmias cardíacas pós-operatórias, especialmente Fibrilação Atrial, em idosos?", "options": {"a": "Sódio.", "b": "Cálcio.", "c": "Magnésio.", "d": "Magnésio e Potássio.", "e": "Cloro."}, "answer": "d", "rationale": "A hipocalemia e a hipomagnesemia são gatilhos frequentes para arritmias atriais e ventriculares devido à alteração do potencial de ação cardíaco.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Incorreta, embora o magnésio seja importante, o potássio é o mais comum.", "d": "Correta. A correção de ambos é fundamental na profilaxia e tratamento das arritmias.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Clínica Médica", "Pós-operatório", "Arritmia", "Eletrólitos"]}', 59, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente feminina, 32 anos, submetida a esplenectomia de urgência por trauma. Recebeu alta hospitalar no 5º DPO sem intercorrências. Qual a orientação obrigatória em relação à imunização (vacinação) que esta paciente deve receber?", "options": {"a": "Não precisa de vacinas se não tiver febre.", "b": "Vacinação contra germes encapsulados (Pneumococo, Meningococo e Haemophilus) preferencialmente 14 dias após a cirurgia ou na alta.", "c": "Apenas vacina contra Tétano.", "d": "Vacina contra Hepatite B.", "e": "Imunização passiva com imunoglobulina polivalente mensal."}, "answer": "b", "rationale": "Pacientes asplênicos têm alto risco de sepse fulminante por bactérias encapsuladas. A imunização reduz drasticamente esse risco. Em esplenectomias de urgência, vacina-se na alta ou cerca de 2 semanas depois (esperando a recuperação imune do trauma).", "option_rationales": {"a": "Incorreta. A asplenia é um estado de imunodeficiência para esses germes.", "b": "Correta. Conduta padrão em pacientes esplenectomizados.", "c": "Incorreta. Insuficiente.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Esplenectomia", "Vacinação"]}', 60, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual o sinal clínico precoce mais sugestivo de fístula salivar (ou fístula de anastomose cervical) após uma esofagectomia com anastomose no pescoço?", "options": {"a": "Febre alta e choque.", "b": "Eritema cervical e saída de saliva ou conteúdo gástrico pelo dreno cervical ou pela ferida.", "c": "Hipoacusia súbita.", "d": "Disfonia leve.", "e": "Desvio da traqueia."}, "answer": "b", "rationale": "As fístulas cervicais são mais comuns que as intratorácicas, mas geralmente mais benignas, manifestando-se com sinais inflamatórios locais e drenagem de conteúdo alimentar/saliva.", "option_rationales": {"a": "Incorreta. Sugere fístula torácica com mediastinite.", "b": "Correta. Apresentação típica da fístula cervical.", "c": "Incorreta. Sem relação.", "d": "Incorreta. Sugere lesão de nervo recorrente.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia do Aparelho Digestivo", "Pós-operatório", "Fístula", "Esofagectomia"]}', 61, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório imediato de um paciente jovem, esportista, que realizou artroscopia de joelho eletiva. Evolui com retenção urinária súbita. Qual a causa mais comum desse fenômeno em pacientes jovens operados sob raquianestesia ou peridural?", "options": {"a": "Hiperplasia prostática benigna oculta.", "b": "Efeito anticolinérgico dos fármacos anestésicos e bloqueio simpático/parassimpático sacral.", "c": "Cálculo vesical.", "d": "Desidratação severa.", "e": "Insuficiência renal aguda por AINEs."}, "answer": "b", "rationale": "A anestesia do neuroeixo bloqueia os nervos responsáveis pela contração do detrusor e relaxamento do esfíncter urinário, levando à retenção, mesmo em pacientes sem doença urológica prévia.", "option_rationales": {"a": "Incorreta. Improvável no jovem.", "b": "Correta. Principal causa farmacológica/técnica.", "c": "Incorreta.", "d": "Incorreta. Desidratação daria oligúria por falta de produção, não retenção com bexiga cheia.", "e": "Incorreta. Teria anúria/oligúria."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Retenção Urinária"]}', 62, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente submetido a cirurgia abdominal alta evolui no 5º DPO com febre e tosse purulenta. Raio-x mostra infiltrado alveolar em base direita. O paciente está entubado desde a cirurgia. O diagnóstico de pneumonia associada ao ventilador (PAV) é suspeitado. Qual o critério temporal para definir uma pneumonia como hospitalar?", "options": {"a": "Ocorre em menos de 12 horas da internação.", "b": "Ocorre após 48 horas da internação ou do procedimento cirúrgico.", "c": "Ocorre após 30 dias da alta.", "d": "Ocorre apenas se o paciente estiver na UTI.", "e": "Não há critério temporal, apenas microbianos."}, "answer": "b", "rationale": "A infecção nosocomial/hospitalar é aquela que se manifesta após 48-72h da admissão, período suficiente para excluir incubação prévia.", "option_rationales": {"a": "Incorreta. Sugere infecção comunitária.", "b": "Correta. Definição epidemiológica padrão.", "c": "Incorreta. Esse é o prazo para infecção do sítio cirúrgico.", "d": "Incorreta. Pode ocorrer em enfermaria.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Pós-operatório", "Pneumonia Hospitalar", "Infecção"]}', 63, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Durante uma laparotomia exploradora por trauma, observa-se uma lesão de duodeno em sua segunda porção (território retroperitoneal). O cirurgião decide realizar o reparo primário. Qual a principal complicação pós-operatória temida nessas lesões e qual o sinal clínico característico?", "options": {"a": "Fístula duodenal; drenagem biliar e abscesso em retroperitônio.", "b": "Gastrite erosiva; hematêmese.", "c": "Colecistite; dor em HD.", "d": "Pancreatite; amilase alta.", "e": "Obstrução pilórica; vômitos gástricos."}, "answer": "a", "rationale": "A fístula duodenal é de difícil manejo devido ao alto débito e presença de bile e suco pancreático, que são extremamente corrosivos e causam infecções graves no retroperitônio.", "option_rationales": {"a": "Correta. Evolução clássica de lesão duodenal complexa.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia de Trauma", "Pós-operatório", "Fístula Duodenal", "Complicações"]}', 64, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a amputação de membro inferior direito por isquemia grave queixa-se no 4º DPO de dor intensa no pé direito, descrevendo-a como queimação e choque, mesmo o membro tendo sido removido. Qual a classificação desta dor e o tratamento adjuvante recomendado?", "options": {"a": "Dor nociceptiva; uso de opioides em altas doses.", "b": "Dor do membro fantasma; uso de anticonvulsivantes (Gabapentina/Pregabalina) e antidepressivos tricíclicos.", "c": "Simulação; encaminhamento à psiquiatria.", "d": "Dor psicossomática; placebo.", "e": "Osteomielite do coto; antibióticos."}, "answer": "b", "rationale": "A dor do membro fantasma é uma dor neuropática causada pela reorganização cortical após a perda do membro. O tratamento envolve medicações para dor neuropática e terapia de espelho.", "option_rationales": {"a": "Incorreta. Opioides têm eficácia limitada para dor neuropática crônica.", "b": "Correta. Quadro clínico e manejo farmacológico corretos.", "c": "Incorreta. É um fenômeno fisiológico documentado.", "d": "Incorreta. É real e incapacitante.", "e": "Incorreta. A dor no ''pé'' inexistente é diagnóstica de membro fantasma, não de infecção local do coto."}, "difficulty": "media", "tags": ["Ortopedia", "Pós-operatório", "Membro Fantasma", "Dor Neuropática"]}', 65, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia de ressecção de tumor de cólon, o paciente desenvolve quadro de tosse e dispneia leve. A ausculta pulmonar revela diminuição do murmúrio vesicular em bases pulmonares e macicez à percussão. Radiografia mostra velamento dos seios costofrênicos bilaterais. Qual a conduta inicial recomendada para um derrame pleural pós-operatório pequeno e assintomático?", "options": {"a": "Toracocentese diagnóstica imediata em ambos os lados.", "b": "Observação clínica e estímulo à fisioterapia respiratória.", "c": "Drenagem de tórax bilateral de urgência.", "d": "Antibioticoterapia para empiema pleural.", "e": "Restrição hídrica severa para desidratar o paciente."}, "answer": "b", "rationale": "Pequenos derrames pleurais são comuns e geralmente secundários a atelectasias ou resposta inflamatória leve (derrames simpáticos). Se assintomáticos, costumam resolver com a expansão pulmonar e deambulação.", "option_rationales": {"a": "Incorreta. Invasivo e desnecessário se o derrame for pequeno/assintomático.", "b": "Correta. Manejo conservador padrão inicial.", "c": "Incorreta. Indicado apenas para grandes derrames, empiema ou pneumotórax.", "d": "Incorreta. Só se houvesse febre e sinais de infecção do líquido.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Pós-operatório", "Derrame Pleural", "Manejo"]}', 66, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 50 anos submetido a bypass gástrico por videolaparoscopia apresenta taquicardia (FC 120 bpm) persistente nas primeiras 12 h de pós-operatório, sem outras queixas. O cirurgião está preocupado com uma possível fístula na anastomose gastrojejunal. Qual a importância da taquicardia nesse cenário específico?", "options": {"a": "É um achado normal de ansiedade pós-operatória.", "b": "É frequentemente o sinal clínico mais precoce e sensível de uma fístula ou complicação grave na cirurgia bariátrica.", "c": "Sugere apenas dor mal controlada.", "d": "Indica necessariamente embolia pulmonar.", "e": "Nenhuma relevância na ausência de febre."}, "answer": "b", "rationale": "Na cirurgia bariátrica, a taquicardia inexplicada (> 120 bpm) é um marcador de alerta máximo para deiscência de sutura/fístula, mesmo na ausência de dor abdominal típica, devido à obesidade que mascara sinais peritoneais.", "option_rationales": {"a": "Incorreta. Diagnóstico de exclusão perigoso.", "b": "Correta. Regra de ouro na cirurgia bariátrica.", "c": "Incorreta. Deve-se afastar o pior primeiro.", "d": "Incorreta. É um diferencial, mas a fístula é a preocupação primária do cirurgião.", "e": "Incorreta. Febre pode ser tardia."}, "difficulty": "moderada", "tags": ["Cirurgia Bariátrica", "Pós-operatório", "Fístula", "Alerta Clínico"]}', 67, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 8º DPO de uma laparotomia por trauma, nota-se que a pele ao redor da ferida operatória está edemaciada e, à pressão digital, sente-se uma crepitação sugestiva de ar no subcutâneo. O paciente está febril (39°C) e toxemiado. Qual o diagnóstico mais provável e a ação imediata?", "options": {"a": "Enfisema subcutâneo por tosse; apenas observação.", "b": "Infecção por anaeróbios (ex: Fascite necrotizante ou Gangrena gasosa); desbridamento cirúrgico agressivo e imediato.", "c": "Seroma infectado; punção aspirativa.", "d": "Reação à tela; remoção seletiva da tela.", "e": "Celulite por Estafilococo; antibiótico oral."}, "answer": "b", "rationale": "A crepitação (gás) associada a sinais sistêmicos de sepse indica infecção necrotizante por germes produtores de gás (anaeróbios). É uma emergência cirúrgica extrema.", "option_rationales": {"a": "Incorreta. Enfisema por tosse não causa febre alta e toxemia.", "b": "Correta. Conduta de salvação de vida e diagnóstico clínico agressivo.", "c": "Incorreta. Insuficiente.", "d": "Incorreta.", "e": "Incorreta. S. aureus não costuma produzir gás rápido assim."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Fascite Necrosante", "Emergência"]}', 68, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A profilaxia para úlcera de estresse com inibidores da bomba de prótons ou bloqueadores H2 deve ser prescrita em pacientes cirúrgicos. Qual o perfil de paciente que mais se beneficia dessa profilaxia, de acordo com as evidências atuais?", "options": {"a": "Todos os pacientes submetidos a qualquer cirurgia eletiva.", "b": "Pacientes em ventilação mecânica prolongada (> 48h) ou com distúrbios de coagulação em ambiente de UTI.", "c": "Pacientes jovens submetidos a apendicectomia.", "d": "Pacientes ambulatoriais operados por hérnia inguinal.", "e": "Pacientes alérgicos a dipirona."}, "answer": "b", "rationale": "A profilaxia de úlcera de estresse não deve ser universal, pois aumenta o risco de pneumonia nosocomial. As indicações clássicas e comprovadas são ventilação mecânica e coagulopatia em pacientes graves.", "option_rationales": {"a": "Incorreta. Uso excessivo desnecessário.", "b": "Correta. Indicações de alto risco bem estabelecidas.", "c": "Incorreta. Risco de sangramento gástrico é quase zero.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Profilaxia", "Úlcera de Estresse"]}', 69, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente idoso submetido a ressecção de próstata (RTU) desenvolve agitação, náuseas e hipertensão severa seguida de hipotensão e bradicardia no pós-operatório imediato. Laboratório mostra Sódio de 118 mEq/L. Qual a provável causa desta complicação neurológica relacionada ao tipo de cirurgia?", "options": {"a": "IAM incidental.", "b": "Síndrome de RTU (intoxicação hídrica por absorção do líquido de irrigação).", "c": "Hemorragia prostática maciça.", "d": "Efeito colateral da anestesia geral.", "e": "Urossepse fulminante."}, "answer": "b", "rationale": "A síndrome da RTU ocorre pela absorção sistêmica dos fluidos de irrigação hipotônicos (ex: glicina ou água destilada) usados durante o procedimento, levando a hiponatremia dilucional aguda e edema cerebral.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação urológica clássica.", "c": "Incorreta. Causaria taquicardia e choque, não necessariamente hiponatremia tão grave.", "d": "Incorreta.", "e": "Incorreta. Septicemia causaria febre e hipotensão precoce, sem hiponatremia aguda intensa típica."}, "difficulty": "media", "tags": ["Urologia", "Pós-operatório", "Síndrome de RTU", "Hiponatremia"]}', 70, 'draft')
